defmodule LynxPhaseFixture.Laws do
  @compile :debug_info
  use Lynx.Laws

  law partial,
    expects: LynxPhaseFixture.Native.consume_chunks(10, 3, 4) == {true, true, 7},
    proof: ~LEAN"""
    set_option maxHeartbeats 16000000 in
    set_option maxRecDepth 8192 in
    refine ⟨0, ?_⟩
    intro depth enough elapsed events last outcome run terminal
    apply terminal.outcome_eq.symm.trans
    apply Lynx.Outcome.eq_of_isTrue
    apply Lynx.Concurrent.checkPost_sound (depth := 384)
      (accept := fun config => config.outcome.isTrue) ?_ run terminal
    clear enough events last outcome run terminal
    cbv
    """

  law complete,
    expects: LynxPhaseFixture.Native.consume_chunks(10, 6, 4) == {true, true, 10},
    proof: ~LEAN"""
